//! Pure-Rust port of the mapbox earcut polygon triangulation algorithm.
//!
//! Uses an arena `Vec<Node>` with `usize` indices and `Option<usize>` links,
//! mirroring the pointer-based C++ implementation exactly so that output
//! ordering matches byte-for-byte.

pub type Index = u32;

#[derive(Clone)]
struct Node {
    i: usize, // flat index into the points array (vertex_index * dim)
    x: f64,
    y: f64,
    prev: Option<usize>,
    next: Option<usize>,
    prev_z: Option<usize>,
    next_z: Option<usize>,
    z: i32,
}

pub struct Earcut {
    nodes: Vec<Node>,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

impl Earcut {
    fn node(&self, idx: usize) -> &Node {
        &self.nodes[idx]
    }

    fn new_node(&mut self, i: usize, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: None,
            next: None,
            prev_z: None,
            next_z: None,
            z: 0,
        });
        self.nodes.len() - 1
    }
}

/// Triangulate a single-ring polygon (no holes) given as flat [x0,y0,x1,y1,...].
pub fn earcut(points: &[f64]) -> Vec<Index> {
    let dim = 2;
    let len = points.len() / dim;
    let mut ec = Earcut {
        nodes: Vec::new(),
        min_x: 0.0,
        min_y: 0.0,
        inv_size: 0.0,
    };
    let mut indices: Vec<Index> = Vec::new();

    let outer_node = linked_list(&mut ec, points, 0, len * dim, dim, true);
    let outer_node = match outer_node {
        Some(n) => n,
        None => return indices,
    };
    if ec.node(outer_node).prev == ec.node(outer_node).next {
        return indices;
    }

    // no holes

    if len > 80 {
        let mut min_x = f64::INFINITY;
        let mut min_y = f64::INFINITY;
        let mut max_x = f64::NEG_INFINITY;
        let mut max_y = f64::NEG_INFINITY;
        for i in (0..len * dim).step_by(dim) {
            let x = points[i];
            let y = points[i + 1];
            if x < min_x {
                min_x = x;
            }
            if y < min_y {
                min_y = y;
            }
            if x > max_x {
                max_x = x;
            }
            if y > max_y {
                max_y = y;
            }
        }
        ec.min_x = min_x;
        ec.min_y = min_y;
        // minX, minY, maxX and maxY are stored to be used in z-order calculation
        let mut inv = f64::max(max_x - min_x, max_y - min_y);
        inv = if inv != 0.0 { 32767.0 / inv } else { 0.0 };
        ec.inv_size = inv;
    }

    earcut_linked(&mut ec, Some(outer_node), &mut indices, 0);
    indices
}

fn signed_area(data: &[f64], start: usize, end: usize, dim: usize) -> f64 {
    let mut sum = 0.0;
    let mut i = start;
    let mut j = end - dim;
    while i < end {
        sum += (data[j] - data[i]) * (data[i + 1] + data[j + 1]);
        j = i;
        i += dim;
    }
    sum
}

fn area(ec: &Earcut, p: usize, q: usize, r: usize) -> f64 {
    let (p, q, r) = (ec.node(p), ec.node(q), ec.node(r));
    (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
}

fn equals(ec: &Earcut, p1: usize, p2: usize) -> bool {
    ec.node(p1).x == ec.node(p2).x && ec.node(p1).y == ec.node(p2).y
}

fn intersects(ec: &Earcut, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
    if (equals(ec, p1, q1) && equals(ec, p2, q2)) || (equals(ec, p1, q2) && equals(ec, p2, q1)) {
        return true;
    }
    (area(ec, p1, q1, p2) > 0.0) != (area(ec, p1, q1, q2) > 0.0)
        && (area(ec, p2, q2, p1) > 0.0) != (area(ec, p2, q2, q1) > 0.0)
}

#[allow(clippy::too_many_arguments)]
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

fn locally_inside(ec: &Earcut, a: usize, b: usize) -> bool {
    let (ap, an) = (ec.node(a).prev.unwrap(), ec.node(a).next.unwrap());
    if area(ec, ap, a, an) < 0.0 {
        area(ec, a, b, an) >= 0.0 && area(ec, a, ap, b) >= 0.0
    } else {
        area(ec, a, b, ap) < 0.0 || area(ec, a, an, b) < 0.0
    }
}

fn middle_inside(ec: &Earcut, a: usize, b: usize) -> bool {
    let px = (ec.node(a).x + ec.node(b).x) / 2.0;
    let py = (ec.node(a).y + ec.node(b).y) / 2.0;
    let mut inside = false;
    let mut p = a;
    loop {
        let pn = ec.node(p).next.unwrap();
        let (px_, py_, nx, ny) = (ec.node(p).x, ec.node(p).y, ec.node(pn).x, ec.node(pn).y);
        if (py_ > py) != (ny > py)
            && ny != py_
            && px < (nx - px_) * (py - py_) / (ny - py_) + px_
        {
            inside = !inside;
        }
        p = pn;
        if p == a {
            break;
        }
    }
    inside
}

fn insert_node(ec: &mut Earcut, i: usize, x: f64, y: f64, last: Option<usize>) -> usize {
    let p = ec.new_node(i, x, y);
    match last {
        None => {
            ec.nodes[p].prev = Some(p);
            ec.nodes[p].next = Some(p);
        }
        Some(last) => {
            let ln = ec.nodes[last].next;
            ec.nodes[p].next = ln;
            ec.nodes[p].prev = Some(last);
            ec.nodes[ln.unwrap()].prev = Some(p);
            ec.nodes[last].next = Some(p);
        }
    }
    p
}

fn remove_node(ec: &mut Earcut, p: usize) {
    let (pp, pn, pz, nz) = {
        let n = ec.node(p);
        (n.prev, n.next, n.prev_z, n.next_z)
    };
    ec.nodes[pn.unwrap()].prev = pp;
    ec.nodes[pp.unwrap()].next = pn;
    if let Some(pz) = pz {
        ec.nodes[pz].next_z = nz;
    }
    if let Some(nz) = nz {
        ec.nodes[nz].prev_z = pz;
    }
}

fn linked_list(
    ec: &mut Earcut,
    data: &[f64],
    start: usize,
    end: usize,
    dim: usize,
    clockwise: bool,
) -> Option<usize> {
    let mut last: Option<usize> = None;
    if clockwise == (signed_area(data, start, end, dim) > 0.0) {
        let mut i = start;
        while i < end {
            last = Some(insert_node(ec, i, data[i], data[i + 1], last));
            i += dim;
        }
    } else {
        let mut i = end;
        while i > start {
            i -= dim;
            last = Some(insert_node(ec, i, data[i], data[i + 1], last));
        }
    }
    if let Some(l) = last {
        let ln = ec.node(l).next.unwrap();
        if equals(ec, l, ln) {
            remove_node(ec, l);
            last = Some(ln);
        }
    }
    last
}

fn filter_points(ec: &mut Earcut, start: usize, end: Option<usize>) -> usize {
    let mut end = end.unwrap_or(start);
    let mut p = start;
    loop {
        let mut again = false;
        let (pp, pn) = (ec.node(p).prev.unwrap(), ec.node(p).next.unwrap());
        if equals(ec, p, pn) || area(ec, pp, p, pn) == 0.0 {
            remove_node(ec, p);
            p = pp;
            end = pp;
            if p == ec.node(p).next.unwrap() {
                break;
            }
            again = true;
        } else {
            p = pn;
        }
        if !(again || p != end) {
            break;
        }
    }
    end
}

fn is_ear(ec: &Earcut, ear: usize) -> bool {
    let (a, b, c) = (
        ec.node(ear).prev.unwrap(),
        ear,
        ec.node(ear).next.unwrap(),
    );
    if area(ec, a, b, c) >= 0.0 {
        return false;
    }
    let (ax, ay, bx, by, cx, cy) = (
        ec.node(a).x,
        ec.node(a).y,
        ec.node(b).x,
        ec.node(b).y,
        ec.node(c).x,
        ec.node(c).y,
    );
    let mut p = ec.node(ear).next.unwrap();
    p = ec.node(p).next.unwrap();
    while p != ec.node(ear).prev.unwrap() {
        let (pp, pn) = (ec.node(p).prev.unwrap(), ec.node(p).next.unwrap());
        if point_in_triangle(ax, ay, bx, by, cx, cy, ec.node(p).x, ec.node(p).y)
            && area(ec, pp, p, pn) >= 0.0
        {
            return false;
        }
        p = pn;
    }
    true
}

fn z_order(ec: &Earcut, x: f64, y: f64) -> i32 {
    // coords are transformed into non-negative 15-bit integer range
    let mut xi = ((x - ec.min_x) * ec.inv_size) as i32;
    let mut yi = ((y - ec.min_y) * ec.inv_size) as i32;
    for v in [&mut xi, &mut yi] {
        *v = (*v | v.wrapping_shl(8)) & 0x00FF_00FF;
        *v = (*v | v.wrapping_shl(4)) & 0x0F0F_0F0F;
        *v = (*v | v.wrapping_shl(2)) & 0x3333_3333;
        *v = (*v | v.wrapping_shl(1)) & 0x5555_5555;
    }
    xi | yi.wrapping_shl(1)
}

fn index_curve(ec: &mut Earcut, start: usize) {
    let mut p = start;
    loop {
        if ec.node(p).z == 0 {
            let z = z_order(ec, ec.node(p).x, ec.node(p).y);
            ec.nodes[p].z = z;
        }
        let (pp, pn) = (ec.node(p).prev.unwrap(), ec.node(p).next.unwrap());
        ec.nodes[p].prev_z = Some(pp);
        ec.nodes[p].next_z = Some(pn);
        p = pn;
        if p == start {
            break;
        }
    }
    let pz = ec.node(p).prev_z.unwrap();
    ec.nodes[pz].next_z = None;
    ec.nodes[p].prev_z = None;
    sort_linked(ec, Some(p));
}

fn sort_linked(ec: &mut Earcut, list: Option<usize>) -> Option<usize> {
    let mut list = list;
    let mut in_size: usize = 1;
    loop {
        let mut p = list;
        list = None;
        let mut tail: Option<usize> = None;
        let mut num_merges = 0;
        while let Some(mut p_idx) = p {
            num_merges += 1;
            let mut q = Some(p_idx);
            let mut p_size = 0;
            for _ in 0..in_size {
                p_size += 1;
                q = ec.node(q.unwrap()).next_z;
                if q.is_none() {
                    break;
                }
            }
            let mut q_size = in_size;
            while p_size > 0 || (q_size > 0 && q.is_some()) {
                let e: usize;
                if p_size == 0 {
                    e = q.unwrap();
                    q = ec.node(e).next_z;
                    q_size -= 1;
                } else if q_size == 0 || q.is_none() {
                    e = p_idx;
                    p_idx = ec.node(e).next_z.unwrap();
                    p_size -= 1;
                } else if ec.node(p_idx).z <= ec.node(q.unwrap()).z {
                    e = p_idx;
                    p_idx = ec.node(e).next_z.unwrap();
                    p_size -= 1;
                } else {
                    e = q.unwrap();
                    q = ec.node(e).next_z;
                    q_size -= 1;
                }
                match tail {
                    Some(t) => ec.nodes[t].next_z = Some(e),
                    None => list = Some(e),
                }
                ec.nodes[e].prev_z = tail;
                tail = Some(e);
            }
            p = q;
        }
        ec.nodes[tail.unwrap()].next_z = None;
        if num_merges <= 1 {
            return list;
        }
        in_size *= 2;
    }
}

fn is_ear_hashed(ec: &Earcut, ear: usize) -> bool {
    let (a, b, c) = (
        ec.node(ear).prev.unwrap(),
        ear,
        ec.node(ear).next.unwrap(),
    );
    if area(ec, a, b, c) >= 0.0 {
        return false;
    }
    let (ax, ay, bx, by, cx, cy) = (
        ec.node(a).x,
        ec.node(a).y,
        ec.node(b).x,
        ec.node(b).y,
        ec.node(c).x,
        ec.node(c).y,
    );
    // triangle bbox
    let min_tx = f64::min(ax, f64::min(bx, cx));
    let min_ty = f64::min(ay, f64::min(by, cy));
    let max_tx = f64::max(ax, f64::max(bx, cx));
    let max_ty = f64::max(ay, f64::max(by, cy));
    // z-order range for the current triangle bbox
    let min_z = z_order(ec, min_tx, min_ty);
    let max_z = z_order(ec, max_tx, max_ty);

    let mut p = ec.node(ear).next_z;
    while let Some(pi) = p {
        if ec.node(pi).z > max_z {
            break;
        }
        let (pp, pn) = (ec.node(pi).prev.unwrap(), ec.node(pi).next.unwrap());
        if pi != ec.node(ear).prev.unwrap()
            && pi != ec.node(ear).next.unwrap()
            && point_in_triangle(ax, ay, bx, by, cx, cy, ec.node(pi).x, ec.node(pi).y)
            && area(ec, pp, pi, pn) >= 0.0
        {
            return false;
        }
        p = ec.node(pi).next_z;
    }
    let mut p = ec.node(ear).prev_z;
    while let Some(pi) = p {
        if ec.node(pi).z < min_z {
            break;
        }
        let (pp, pn) = (ec.node(pi).prev.unwrap(), ec.node(pi).next.unwrap());
        if pi != ec.node(ear).prev.unwrap()
            && pi != ec.node(ear).next.unwrap()
            && point_in_triangle(ax, ay, bx, by, cx, cy, ec.node(pi).x, ec.node(pi).y)
            && area(ec, pp, pi, pn) >= 0.0
        {
            return false;
        }
        p = ec.node(pi).prev_z;
    }
    true
}

fn cure_local_intersections(ec: &mut Earcut, start: usize, indices: &mut Vec<Index>) -> usize {
    let mut p = start;
    let mut start = start;
    loop {
        let (a, pn) = (ec.node(p).prev.unwrap(), ec.node(p).next.unwrap());
        let b = ec.node(pn).next.unwrap();
        if !equals(ec, a, b)
            && intersects(ec, a, p, pn, b)
            && locally_inside(ec, a, b)
            && locally_inside(ec, b, a)
        {
            indices.push((ec.node(a).i / 2) as Index);
            indices.push((ec.node(p).i / 2) as Index);
            indices.push((ec.node(b).i / 2) as Index);
            remove_node(ec, p);
            // in C++, p->next is read after removeNode(p); removal does not
            // alter p's own links, so this equals the captured pn
            remove_node(ec, pn);
            p = b;
            start = b;
        }
        p = ec.node(p).next.unwrap();
        if p == start {
            break;
        }
    }
    p
}

fn is_valid_diagonal(ec: &Earcut, a: usize, b: usize) -> bool {
    let (an, ap) = (ec.node(a).next.unwrap(), ec.node(a).prev.unwrap());
    let bi = ec.node(b).i;
    ec.node(an).i != bi
        && ec.node(ap).i != bi
        && !intersects_polygon(ec, a, b)
        && ((locally_inside(ec, a, b)
            && locally_inside(ec, b, a)
            && middle_inside(ec, a, b)
            && (area(ec, ap, a, ec.node(b).prev.unwrap()) != 0.0
                || area(ec, a, ec.node(b).prev.unwrap(), b) != 0.0))
            || (equals(ec, a, b)
                && area(ec, ap, a, an) != 0.0
                && area(ec, ec.node(b).prev.unwrap(), b, ec.node(b).next.unwrap()) != 0.0))
}

fn intersects_polygon(ec: &Earcut, a: usize, b: usize) -> bool {
    let (ai, bi) = (ec.node(a).i, ec.node(b).i);
    let mut p = a;
    loop {
        let pn = ec.node(p).next.unwrap();
        if ec.node(p).i != ai
            && ec.node(pn).i != ai
            && ec.node(p).i != bi
            && ec.node(pn).i != bi
            && intersects(ec, p, pn, a, b)
        {
            return true;
        }
        p = pn;
        if p == a {
            break;
        }
    }
    false
}

fn split_polygon(ec: &mut Earcut, a: usize, b: usize) -> usize {
    let (ai, ax, ay) = (ec.node(a).i, ec.node(a).x, ec.node(a).y);
    let (bi, bx, by) = (ec.node(b).i, ec.node(b).x, ec.node(b).y);
    let a2 = ec.new_node(ai, ax, ay);
    let b2 = ec.new_node(bi, bx, by);
    let an = ec.node(a).next.unwrap();
    let bp = ec.node(b).prev.unwrap();
    ec.nodes[a].next = Some(b);
    ec.nodes[b].prev = Some(a);
    ec.nodes[a2].next = Some(an);
    ec.nodes[an].prev = Some(a2);
    ec.nodes[b2].next = Some(a2);
    ec.nodes[a2].prev = Some(b2);
    ec.nodes[bp].next = Some(b2);
    ec.nodes[b2].prev = Some(bp);
    b2
}

fn split_earcut(ec: &mut Earcut, start: usize, indices: &mut Vec<Index>) {
    let mut a = start;
    loop {
        let mut b = ec.node(ec.node(a).next.unwrap()).next.unwrap();
        while b != ec.node(a).prev.unwrap() {
            if ec.node(a).i != ec.node(b).i && is_valid_diagonal(ec, a, b) {
                let c = split_polygon(ec, a, b);
                a = filter_points(ec, a, ec.node(a).next);
                let c = filter_points(ec, c, ec.node(c).next);
                earcut_linked(ec, Some(a), indices, 0);
                earcut_linked(ec, Some(c), indices, 0);
                return;
            }
            b = ec.node(b).next.unwrap();
        }
        a = ec.node(a).next.unwrap();
        if a == start {
            break;
        }
    }
}

fn earcut_linked(ec: &mut Earcut, ear: Option<usize>, indices: &mut Vec<Index>, pass: u32) {
    let mut ear = match ear {
        Some(e) => e,
        None => return,
    };
    // interlink polygon nodes in z-order
    if pass == 0 && ec.inv_size != 0.0 {
        index_curve(ec, ear);
    }
    let mut stop = ear;
    // iterate through ears, slicing them one by one
    while ec.node(ear).prev != ec.node(ear).next {
        let prev = ec.node(ear).prev.unwrap();
        let next = ec.node(ear).next.unwrap();
        let is_ear = if ec.inv_size != 0.0 {
            is_ear_hashed(ec, ear)
        } else {
            is_ear(ec, ear)
        };
        if is_ear {
            indices.push((ec.node(prev).i / 2) as Index);
            indices.push((ec.node(ear).i / 2) as Index);
            indices.push((ec.node(next).i / 2) as Index);
            remove_node(ec, ear);
            // skipping the next vertex leads to less sliver triangles
            ear = ec.node(next).next.unwrap();
            stop = ear;
            continue;
        }
        ear = next;
        // if we looped through the whole remaining polygon and can't find any more ears
        if ear == stop {
            match pass {
                0 => {
                    let e = filter_points(ec, ear, None);
                    earcut_linked(ec, Some(e), indices, 1);
                }
                1 => {
                    let f = filter_points(ec, ear, None);
                    let e = cure_local_intersections(ec, f, indices);
                    earcut_linked(ec, Some(e), indices, 2);
                }
                2 => {
                    split_earcut(ec, ear, indices);
                }
                _ => {}
            }
            break;
        }
    }
}

